insert into parties (id, name, short_name, orientation, color) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:party:nouvelle-energie'), 'Nouvelle Énergie', 'NE', 'droite', '#0d9488') on conflict (id) do nothing;
insert into candidates (id, slug, name, photo_url, party_id, biography, official_website, election_id, is_demo, order_index) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate:david-lisnard'), 'david-lisnard', 'David Lisnard', '/candidates/david-lisnard.jpg', uuid_generate_v5(uuid_ns_url(), 'poliscope:party:nouvelle-energie'), 'Né le 2 février 1969 à Limoges, David Lisnard est diplômé de l''Institut d''études politiques de Bordeaux. Maire de Cannes depuis 2014 et président de l''Association des maires de France depuis 2021, il a quitté Les Républicains le 31 mars 2026 pour se présenter à la présidentielle de 2027 via le mouvement Nouvelle Énergie, qu''il préside.', 'https://www.unenouvelleenergie.fr/', uuid_generate_v5(uuid_ns_url(), 'poliscope:election:presidentielle-2027'), false, 10) on conflict (id) do nothing;
insert into proposals (id, candidate_id, theme_id, title, summary, description, source_name, source_url, published_at, verified_at, status, tags) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:proposal:proposal-64'), uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate:david-lisnard'), uuid_generate_v5(uuid_ns_url(), 'poliscope:theme:retraites'), 'Retraite à 65 ans et capitalisation obligatoire complémentaire', 'Porter l''âge légal à 65 ans et rendre obligatoire une capitalisation complémentaire à la répartition.', 'Le programme prévoit une pension minimale assurée par répartition, complétée par une capitalisation obligatoire sur le reste des cotisations, avec une transition en environ 8 tranches successives vers un encours de capitalisation de 116 milliards d''euros (environ 40 % du montant total des retraites) ; le minimum vieillesse serait porté à 1 000 euros mensuels.', 'Programme de campagne — Nouvelle Énergie', 'https://www.unenouvelleenergie.fr/notre-programme/reussir-une-nouvelle-ambition-francaise/', '2026-07-03', '2026-09-03', 'programme', 'Âge légal, Capitalisation') on conflict (id) do nothing;
insert into proposals (id, candidate_id, theme_id, title, summary, description, source_name, source_url, published_at, verified_at, status, tags) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:proposal:proposal-65'), uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate:david-lisnard'), uuid_generate_v5(uuid_ns_url(), 'poliscope:theme:immigration'), 'Diviser par huit les titres de séjour et durcir les conditions d''entrée', 'Réduire d''un facteur huit la délivrance de titres de séjour et durcir regroupement familial, droit du sol et rétention.', 'Le programme prévoit de revenir sur l''accord franco-algérien de 1968, de diviser par huit la délivrance de titres de séjour, de conditionner le regroupement familial à des critères de ressources et des tests d''intégration, de mettre fin à l''automaticité du droit du sol, d''allonger la rétention administrative à 24 mois, de supprimer l''Aide Médicale d''État (700 millions d''euros d''économies visées), de rétablir le délit de séjour irrégulier, et de conditionner les prestations sociales non contributives à 5 ans de résidence régulière.', 'Programme de campagne — Nouvelle Énergie', 'https://www.unenouvelleenergie.fr/notre-programme/immigration/', '2026-07-03', '2026-09-03', 'programme', 'Titres de séjour, Regroupement familial') on conflict (id) do nothing;
insert into proposals (id, candidate_id, theme_id, title, summary, description, source_name, source_url, published_at, verified_at, status, tags) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:proposal:proposal-66'), uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate:david-lisnard'), uuid_generate_v5(uuid_ns_url(), 'poliscope:theme:securite'), 'Armer les polices municipales et durcir la réponse pénale', 'Étendre les pouvoirs des polices municipales et durcir les peines, dont l''abaissement de la majorité pénale à 16 ans.', 'Le programme prévoit de ramener 50 % des forces de sécurité sur le terrain (contre 37 % actuellement), de permettre aux communes d''armer leur police municipale avec accès aux fichiers, de créer des cellules locales anti-stups sous autorité préfectorale, de supprimer les réductions de peine automatiques, de rétablir des peines plancher pour les récidivistes, de doubler les effectifs des juridictions correctionnelles, et d''abaisser la majorité pénale à 16 ans.', 'Programme de campagne — Nouvelle Énergie', 'https://www.unenouvelleenergie.fr/notre-programme/securite/', '2026-07-03', '2026-09-03', 'programme', 'Police municipale, Justice pénale') on conflict (id) do nothing;
insert into proposals (id, candidate_id, theme_id, title, summary, description, source_name, source_url, published_at, verified_at, status, tags) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:proposal:proposal-67'), uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate:david-lisnard'), uuid_generate_v5(uuid_ns_url(), 'poliscope:theme:economie'), 'Règle d''or budgétaire et dépense publique sous 50 % du PIB', 'Instaurer une règle d''or sur les dépenses de fonctionnement pour ramener la dépense publique sous 50 % du PIB en cinq ans.', 'S''appuyant sur l''exemple de la Suède et de l''Allemagne (une baisse de 8 points de PIB en 10 ans), le programme vise à réduire la dépense publique de 55,6 % à moins de 50 % du PIB sans attendre 2027, via une règle d''or appliquée au fonctionnement (pas à l''investissement), une réduction des tâches administratives de 33 % à 25 % (le taux allemand), et le redéploiement de 450 000 fonctionnaires des bureaux vers le terrain.', 'Programme de campagne — Nouvelle Énergie', 'https://www.unenouvelleenergie.fr/notre-programme/etre-maitre-de-notre-destin/', '2026-07-03', '2026-09-03', 'programme', 'Dépense publique, Fonction publique') on conflict (id) do nothing;
insert into proposals (id, candidate_id, theme_id, title, summary, description, source_name, source_url, published_at, verified_at, status, tags) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:proposal:proposal-68'), uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate:david-lisnard'), uuid_generate_v5(uuid_ns_url(), 'poliscope:theme:economie'), 'Baisse de moitié des impôts de production et contrat de travail unique', 'Supprimer la C3S et alléger la CVAE pour diviser par deux les impôts de production, et fusionner CDI et CDD.', 'La suppression de la C3S et, le cas échéant, de la CVAE représenterait 11,5 milliards d''euros d''allégement, combinés aux 10 milliards déjà prévus par le gouvernement, pour une diminution de moitié des impôts de production (de 2 % à 1 % du PIB). Le programme prévoit aussi un contrat de travail unique fusionnant CDI et CDD, la suppression des charges employeur au niveau du SMIC, et des charges patronales négatives pour l''embauche de bénéficiaires du RSA depuis plus de deux ans.', 'Programme de campagne — Nouvelle Énergie', 'https://www.unenouvelleenergie.fr/notre-programme/reussir-une-nouvelle-ambition-francaise/', '2026-07-03', '2026-09-03', 'programme', 'Fiscalité des entreprises, Emploi') on conflict (id) do nothing;
insert into proposals (id, candidate_id, theme_id, title, summary, description, source_name, source_url, published_at, verified_at, status, tags) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:proposal:proposal-69'), uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate:david-lisnard'), uuid_generate_v5(uuid_ns_url(), 'poliscope:theme:education'), 'Chèque-éducation, autonomie des établissements et +20 % pour les enseignants', 'Instaurer un chèque-éducation, donner l''autonomie de recrutement aux établissements et augmenter les enseignants de 20 % en cinq ans.', 'Le programme prévoit d''abroger la carte scolaire, d''instaurer progressivement un chèque-éducation (financement public équivalent que la famille choisisse le public ou le privé), de donner aux chefs d''établissement la liberté de recruter leurs équipes, d''appliquer leurs méthodes et de gérer leur budget, d''instaurer un certificat de fin de primaire conditionnant l''entrée au collège, d''étendre l''enseignement du grec, du latin et de la philosophie dès le primaire, et d''augmenter les rémunérations enseignantes de 20 % en cinq ans.', 'Programme de campagne — Nouvelle Énergie', 'https://www.unenouvelleenergie.fr/notre-programme/education/', '2026-07-03', '2026-09-03', 'programme', 'Autonomie, Enseignants') on conflict (id) do nothing;
insert into proposals (id, candidate_id, theme_id, title, summary, description, source_name, source_url, published_at, verified_at, status, tags) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:proposal:proposal-70'), uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate:david-lisnard'), uuid_generate_v5(uuid_ns_url(), 'poliscope:theme:sante'), 'Fin des ARS et doublement des étudiants en médecine d''ici 2030', 'Supprimer les Agences régionales de santé et doubler le nombre d''étudiants en médecine d''ici 2030.', 'Le programme prévoit un conventionnement différencié (mieux rembourser les actes en zones sous-dotées qu''en zones saturées), la généralisation de maisons de santé pluridisciplinaires à l''échelle de chaque canton, l''accès direct aux infirmiers, kinés et pharmaciens, la suppression des Agences régionales de santé au profit des préfets et des élus locaux (dont la présidence des conseils d''administration d''hôpitaux rendue aux maires), et le doublement du nombre d''étudiants en médecine d''ici 2030.', 'Programme de campagne — Nouvelle Énergie', 'https://www.unenouvelleenergie.fr/notre-programme/sante/', '2026-07-03', '2026-09-03', 'programme', 'Hôpital public, Accès aux soins') on conflict (id) do nothing;
insert into proposals (id, candidate_id, theme_id, title, summary, description, source_name, source_url, published_at, verified_at, status, tags) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:proposal:proposal-71'), uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate:david-lisnard'), uuid_generate_v5(uuid_ns_url(), 'poliscope:theme:energie'), 'Prolonger les réacteurs nucléaires à 60 ans et construire de nouveaux EPR', 'Faire du nucléaire une priorité stratégique, en prolongeant les réacteurs existants et en construisant de nouveaux EPR et mini-réacteurs.', 'Le programme présente le nucléaire comme une « priorité écologique et stratégique » pour la souveraineté industrielle : prolongation de la durée de vie des réacteurs jusqu''à 60 ans, construction d''EPR de nouvelle génération, déploiement de mini-réacteurs, complétés par une fiscalité carbone de type pollueur-payeur redistribuée aux ménages les plus affectés et neutre pour la compétitivité.', 'Programme de campagne — Nouvelle Énergie', 'https://www.unenouvelleenergie.fr/notre-programme/generer-un-renouveau-civique/', '2026-07-03', '2026-09-03', 'programme', 'Nucléaire, Fiscalité carbone') on conflict (id) do nothing;
